import { createMessageBus } from "@zudojs/messaging";

const bus = createMessageBus();
let failures = 0;

bus.use(async (ctx, next) => {
  try {
    return await next();
  } catch (error) {
    failures += 1;
    throw error;
  }
}, { id: "count-failures" });

bus.on("task.count", async () => 3, { id: "count" });
